s = s.replace("if (this.state.freezeTicksRemaining() > 0) buffs.push(`TIME FROZEN ${(this.state.freezeTicksRemaining() / 60).toFixed(1)}s`)", "if (this.state.bulletTimeTicksRemaining() > 0) buffs.push(`LAST CHANCE ${(this.state.bulletTimeTicksRemaining() / 60).toFixed(1)}s`)")
