Path('tests/combo-powerups.test.ts').write_text('''import { describe, expect, it } from 'vitest'\nimport { GameState, TARGET_ENEMIES } from '../src/game/sim/GameState'\n\nfunction prepKills(state: GameState, count: number): void {\n  for (const enemy of state.enemies.items) enemy.active = false\n  for (let i = 0; i < count; i += 1) {\n    const enemy = state.enemies.items[i]\n    Object.assign(enemy, { active: true, hp: 1, mass: 1, radius: 10, x: 54 + (i % 3) * 8, y: (i - Math.floor(count / 2)) * 3, speed: 0, vx: 0, vy: 0, impulseX: 0, impulseY: 0, staggerTicks: 0 })\n  }\n}\n\ndescribe('combat reward loop v1', () => {\n  it('keeps the active horde intentionally below 60', () => { expect(TARGET_ENEMIES).toBe(48); expect(new GameState(1).enemies.activeCount()).toBe(48) })\n  it('keeps chain scoring but only modestly accelerates normal cutting', () => {\n    const state = new GameState(2); prepKills(state, 12); state.step({ x: 0, y: 0, aimRadians: 0, whirlwind: true })\n    expect(state.comboMultiplier()).toBe(4); expect(state.attackSpeedMultiplier()).toBeGreaterThan(1); expect(state.attackSpeedMultiplier()).toBeLessThanOrEqual(1.12); expect(state.powerups.filter((powerup) => powerup.active)).toHaveLength(0); expect(state.bulletTimeTicksRemaining()).toBe(0)\n  })\n  it('triggers one last-chance bullet-time rescue when HP falls to one', () => {\n    const state = new GameState(3); for (const enemy of state.enemies.items) enemy.active = false; state.player.hp = 2\n    const enemy = state.enemies.items[0]; Object.assign(enemy, { active: true, hp: 1, mass: 1, radius: 12, x: 0, y: 0, speed: 0, vx: 0, vy: 0, impulseX: 0, impulseY: 0, staggerTicks: 0 })\n    state.step({ x: 0, y: 0 }); expect(state.player.hp).toBe(1); expect(state.hasUsedLastChance()).toBe(true); expect(state.bulletTimeTicksRemaining()).toBeGreaterThan(100); expect(state.powerups.filter((powerup) => powerup.active)).toHaveLength(1); expect(state.events.some((event) => event.type === 'bullet-time')).toBe(true)\n  })\n})\n''')
Path('tests/keyboard-combat-buffer.test.ts').write_text('''import { describe, expect, it } from 'vitest'\nimport { KeyboardCombatBuffer } from '../src/game/input/KeyboardCombatBuffer'\n\ndescribe('keyboard combat buffer', () => {\n  it('holds stab and whirlwind edges across several fixed ticks', () => { const buffer = new KeyboardCombatBuffer(); buffer.queueStab(); buffer.queueWhirlwind(); for (let i = 0; i < 6; i += 1) { const input = buffer.consume(); expect(input.stab).toBe(true); expect(input.whirlwind).toBe(true) } })\n  it('clears all queued edges on restart', () => { const buffer = new KeyboardCombatBuffer(); buffer.queueSlash(); buffer.queueStab(); buffer.queueWhirlwind(); buffer.queueDashRelease(); buffer.clear(); expect(buffer.consume()).toEqual({ slash: false, stab: false, whirlwind: false, dashReleased: false }) })\n})\n''')
Path('tests/level.test.ts').write_text('''import { describe, expect, it } from 'vitest'\nimport { CITY_LEVEL_OBSTACLES, circleOverlapsObstacle } from '../src/game/world/Level'\n\ndescribe('city level geometry', () => { it('provides multiple building blocks and leaves player start open', () => { expect(CITY_LEVEL_OBSTACLES.length).toBeGreaterThanOrEqual(8); expect(CITY_LEVEL_OBSTACLES.some((obstacle) => circleOverlapsObstacle(0, 0, 14, obstacle))).toBe(false) }) })\n''')
Path('docs/RESCUE_LEVEL_V0.md').write_text('''# Rescue + City Level V0\n\nRoutine powerup drops are removed. Combo tiers remain for score, while normal cut-speed bonuses are reduced to 1.04x / 1.08x / 1.12x.\n\nOnce per run, when HP falls to exactly 1, Last Chance fires: enemies/world advance one of every four fixed ticks for 150 ticks (~2.5s), player attacks remain full-rate, the player gets 60 invulnerable ticks, and one nearby LAST BITE pickup appears. LAST BITE heals 2 HP and grants 1.25x cut speed for 120 ticks.\n\nSPACE, E, Q and Shift-release now use fixed-tick buffers matching the responsive mouse input path. Restart clears all buffers.\n\nKenney Pico-8 City CC0 sample map is imported from pinned Tiddybub/2d-assets revision e0cbe0d995554a490d4c182fe9beb8769ffbb606. Its 55x30 8px layout is rendered at 2x under authoritative building collision rectangles, creating streets, alleys and chokepoints.\n''')
